  return (
    <div className="space-y-4">
      <Skeleton className="h-8 w-48" />
      <div className="grid gap-4">
        {[1,2,3].map((i) => (
          <Skeleton key={i} className="h-24 w-full" />
        ))}
      </div>
    </div>
  );
}
```

## Data Hook (no Provider/Context)

```tsx
// components/tasks/tasks-hooks.ts
"use client";

import { useList } from "@refinedev/core";

interface Task {
  id: string;
  title: string;
  status: string;
  assignee: { avatar: string; name: string };
  dueDate: string;
  projectId?: string;
}

export function useTaskData() {
  const { data, isLoading, error } = useList<Task>({
    resource: "tasks",
  });

  return {
    tasks: data?.data ?? [],
    isLoading,
    error,
  };
}
