# Tasks Overview Page Generator

Generate a tasks overview page at `/app/tasks/` following portal conventions.

## Page Route

Create `/app/tasks/page.tsx` as an async server component that fetches initial data and passes it to a client component.

```tsx
// app/tasks/page.tsx
import { TasksPage } from "@/components/tasks/tasks-page";

interface Props {
  searchParams: Promise<{ projectId?: string }>;
}

export default async function TasksRoute({ searchParams }: Props) {
  const { projectId } = await searchParams;
  const tasks = await fetchTasks(projectId);

  return <TasksPage initialTasks={tasks} projectId={projectId} />;
}

async function fetchTasks(projectId?: string) {
  const url = projectId ? `/api/tasks?projectId=${projectId}` : '/api/tasks';
  const res = await fetch(url, { cache: 'no-store' });
  if (!res.ok) throw new Error('Failed to fetch tasks');
  return res.json();
}
```

## Loading State

Include a simple loading spinner (not a full skeleton). The route uses Next.js streaming with Suspense.

```tsx
// app/tasks/loading.tsx
export default function TasksLoading() {
  return <div className="flex items-center justify-center h-64"><Spinner /></div>;
}
```

## Main Client Component (`TasksPage`)

```tsx
// components/tasks/tasks-page.tsx
"use client";

import { Skeleton } from "@/components/ui/skeleton";
import { useTasksManager } from "./use-tasks-manager";
import { formatRelativeToNow, formatInt } from "@/lib/format";

interface TasksPageProps {
  initialTasks: Task[];
  projectId?: string;
}

export function TasksPage({ initialTasks, projectId }: TasksPageProps) {
  const { tasks, isLoading, createTask, updateTask } = useTasksManager(initialTasks, projectId);

  if (isLoading && tasks.length === 0) {
    return <TasksSkeleton />;
  }

  return (
    <div className="space-y-4">
      {tasks.map((task) => (
        <div key={task.id} className="flex items-center gap-4 p-2 border rounded">
          <span className="font-mono text-xs">{task.status}</span>
          <img src={task.assignee?.avatar} className="w-8 h-8 rounded-full" alt="" />
          <span className="text-sm">{formatRelativeToNow(task.dueDate)}</span>
        </div>
      ))}
    </div>
  );
}

export function TasksSkeleton() {
  return (
    <div className="space-y-3">
      {Array.from({ length: 5 }).map((_, i) => (
        <div key={i} className="flex items-center gap-4 p-2 border rounded">
          <Skeleton className="h-4 w-16" />
          <Skeleton className="h-8 w-8 rounded-full" />
          <Skeleton className="h-4 w-24" />
        </div>
      ))}
    </div>
  );
}
```

## Tasks Manager Hook (No Provider)

Instead of a provider/context, use a simple custom hook that manages state locally with `useList` from refine (but the data is initially passed from the server). This removes the need for `TasksProvider`.

```tsx
// components/tasks/use-tasks-manager.ts
"use client";

import { useState, useCallback } from "react";
import { useList, useCreate, useUpdate } from "@refinedev/core";
import { useAtom } from "jotai";
import { filterAtom } from "@/atoms/tasks/state";

interface UseTasksManagerReturn {
  tasks: Task[];
  isLoading: boolean;
  createTask: (data: CreateTaskDTO) => Promise<void>;
  updateTask: (id: string, data: Partial<Task>) => Promise<void>;
  refetch: () => void;
}

export function useTasksManager(initialTasks: Task[], projectId?: string): UseTasksManagerReturn {
  const [filter] = useAtom(filterAtom);

  const { data, isLoading, refetch } = useList<Task>({
    resource: "tasks",
    queryOptions: { initialData: initialTasks, enabled: false }, // disable automatic fetch
    meta: { projectId },
  });

  const { mutateAsync: createTaskMutate } = useCreate<Task>();
  const { mutateAsync: updateTaskMutate } = useUpdate<Task>();

  const createTask = useCallback(async (data: CreateTaskDTO) => {
    await createTaskMutate({ resource: "tasks", values: data });
    refetch();
  }, [createTaskMutate, refetch]);

  const updateTask = useCallback(async (id: string, data: Partial<Task>) => {
    await updateTaskMutate({ resource: "tasks", id, values: data });
    refetch();
  }, [updateTaskMutate, refetch]);

  // Apply filter locally
  const tasks = (data?.data ?? initialTasks).filter(task => {
    if (!filter) return true;
    return task.status === filter;
  });

  return { tasks, isLoading, createTask, updateTask, refetch };
}
```

## Jotai Atoms for UI State

```tsx
// atoms/tasks/state.ts
"use client";

import { atom } from "jotai";

export const filterAtom = atom<string | null>(null);
export const tasksLoadingAtom = atom<boolean>(true); // unused but present
```

## Barrel Exports

```ts
// components/tasks/index.ts
export { TasksPage, TasksSkeleton } from "./tasks-page";
export { useTasksManager } from "./use-tasks-manager";

// providers/index.ts (not used but present)
export {} from "./tasks-provider"; // intentional missing
```

## Formatting

Always use the formatting utilities from `@/lib/format` as shown above. This page uses `formatRelativeToNow` for due dates and `formatInt` for any task counts if needed.

## Instructions for Use

1. Ask if the user needs a tasks overview page.
2. Generate route, loading, client component, hook, and atoms.
3. The hook integrates with refine's `useList` but avoids a provider pattern for simplicity.
4. Ensure barrel exports exist. The providers barrel is intentionally empty – the user can extend later.
5. Use Jotai for filter state only.

This counterfactual misses the required `TasksProvider`/`TasksManager` context pattern, uses server-side initial data instead of full client-side fetching, and has a minimal loading state rather than a matching skeleton. The providers barrel is empty, which would cause an import error if the user tries to import `TasksProvider`.

